(()=>{'use strict';const D=window.SCHEDULE_DATA,E=window.ScheduleEngine,$=id=>document.getElementById(id),days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
const profiles=[['office','9–5','Mon–Fri',[0,1,2,3,4],'09:00','17:00'],['shift','Retail / service','Tue–Sat · 10–6',[1,2,3,4,5],'10:00','18:00'],['health','Healthcare','Mon, Wed, Fri · 7–7',[0,2,4],'07:00','19:00'],['gig','Gig / independent','Set your earning hours',[0,1,2,3,4],'09:00','17:00'],['night','Night shift','Mon–Fri · 10 p.m.–6 a.m.',[0,1,2,3,4],'22:00','06:00'],['custom','My own schedule','Edit days and hours',[0,1,2,3,4],'09:00','17:00']];
let active='office',workdays=[0,1,2,3,4];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const link=u=>/^https:\/\//.test(u||'')?esc(u):'#';const time=n=>{n=(n%1440+1440)%1440;const h=Math.floor(n/60),m=n%60;return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'am':'pm'}`};const len=n=>n>=60?`${Math.floor(n/60)}h${n%60?' '+n%60+'m':''}`:`${n} min`;
function controls(){ $('profiles').innerHTML=profiles.map(p=>`<button data-profile="${p[0]}" aria-pressed="${p[0]===active}" class="${p[0]===active?'active':''}">${p[1]}<small>${p[2]}</small></button>`).join('');$('days').innerHTML=days.map((d,i)=>`<button data-day="${i}" aria-pressed="${workdays.includes(i)}" class="${workdays.includes(i)?'active':''}">${d}</button>`).join(''); }
const services=[...new Set(D.records.map(r=>r.service))].sort();$('service').innerHTML=services.map(s=>`<option>${esc(s)}</option>`).join('');$('service').value='IDNYC enrollment';$('date').textContent=`Source snapshot · ${D.checkedDate}`;
function settings(){let unavailable=[];if($('care').checked){let start=E.minutes($('careStart').value),end=E.minutes($('careEnd').value);unavailable=[0,1,2,3,4].map(d=>[d*1440+start,d*1440+end+(end<=start?1440:0)]);}unavailable.push(...window.Journey.constraints());return {days:workdays,start:$('start').value,end:$('end').value,travel:+$('travel').value,duration:+$('duration').value,wait:+$('wait').value,unavailable};}
function remote(r){return `<details class="route"><summary>Can I do this online?</summary><p>${esc(r.remoteAlternative||'No verified online route in this record. Check the service’s official instructions.')}</p><p>${r.visitRequired===true?'This record identifies a required in-person step.':r.visitRequired===false?'A remote route is offered; check which tasks it covers.':'Whether you need a visit depends on your exact task.'} ${esc(r.appointment||'')}</p><a href="${link(r.sourceUrl)}" target="_blank" rel="noopener">Official instructions ↗</a></details>`;}
function render(){const s=settings();$('assumptions').textContent=`${s.start}–${s.end} · ${s.travel} min each way · ${s.wait? s.wait+' min waiting':'waiting not included'}`;
window.Journey.overview(s);
if(window.AddressPlanner.render(s))return;
const rows=D.records.filter(r=>r.service===$('service').value&&($('borough').value==='all'||r.borough===$('borough').value||r.borough==='Citywide')).map(r=>({r,p:E.planVisit(r,s)}));const known=rows.filter(x=>['fits','overlap'].includes(x.p.kind)).sort((a,b)=>a.p.overlap-b.p.overlap||a.p.start-b.p.start);const best=known[0];let html='';
if(best){const {r,p}=best;html=`<div class="outcome ${p.overlap?'':'fit'}"><p class="eyebrow">BEST MODELED WINDOW IN THIS SELECTION</p><div class="number ${p.overlap?'overlap':''}">${p.overlap?len(p.overlap):'No overlap'}</div><h3>${p.overlap?'of your work time overlaps this '+(r.channel==='in_person'?'trip.':'appointment.'):'with your work schedule.'}</h3><p><strong>${esc(r.name)}</strong> · ${esc(r.borough)}<br>${days[Math.floor(p.start/1440)]}, ${time(p.start)} · ${esc(r.service)}</p><div class="trip"><span>${r.channel==='in_person'?'Leave':'Start'}<strong>${time(p.depart)}</strong></span><span>Appointment + wait<strong>${time(p.start)}–${time(p.finish)}</strong></span><span>${r.channel==='in_person'?'Return':'Finish'}<strong>${time(p.back)}</strong></span><span>Total time<strong>${len(p.back-p.depart)}</strong></span></div><p class="small">Possible window, not a confirmed appointment. ${s.wait?'Waiting is your estimate.':'Waiting time is not included.'} ${r.visitRequired!==true?'A visit may be avoidable—see the online route below.':''} ${active==='gig'?'Changing earning hours may still reduce income.':''} ${active==='night'?'This result does not reserve daytime sleep. Add protected time above.':''}</p>${remote(r)}<details class="route"><summary>Hours, conditions & source</summary><p>${esc(r.hoursText)}</p><p>${esc(r.notes||'')}</p><p>${esc(r.exceptionsText||'')}</p><a href="${link(r.sourceUrl)}" target="_blank" rel="noopener">Published schedule ↗</a></details></div>`;
}else{html=`<div class="outcome"><div class="number">${rows.some(x=>x.p.kind==='blocked')?'No window':'Not enough data'}</div><p>${rows.some(x=>x.p.kind==='blocked')?'The published hours cannot fit this visit around your protected time. Try adjusting your assumptions.':'We can’t calculate a window from the verified hours in this selection.'}</p>${rows[0]?remote(rows[0].r):'Try another borough.'}</div>`;}
const unknown=rows.filter(x=>x.p.kind==='unknown').length,special=rows.some(x=>x.r.scheduleExceptions?.length||x.r.extraHours);html+=`<p class="small">${known.length} regular schedules modeled${unknown?' · '+unknown+' with unverified hours':''}. ${special?'Special-date hours exist; the regular-week model does not include them. Check official details.':''}</p><details id="other"><summary>All ${rows.length} matching locations / channels</summary>${rows.map(({r,p})=>`<article><div><strong>${esc(r.name)}</strong><small>${esc(r.borough)} · ${esc(r.channel.replace('_',' '))}</small><small>${esc(r.hoursText)}</small><a href="${link(r.sourceUrl)}" target="_blank" rel="noopener">Source ↗</a></div><div>${p.kind==='fits'?'No work overlap':p.kind==='overlap'?len(p.overlap)+' work overlap':p.kind==='closed'?'Listed closed':p.kind==='blocked'?'Protected-time conflict':'Hours unverified'}</div></article>`).join('')}</details>`;$('result').innerHTML=html;}
$('profiles').onclick=e=>{const b=e.target.closest('[data-profile]');if(!b)return;const p=profiles.find(x=>x[0]===b.dataset.profile);active=p[0];workdays=[...p[3]];$('start').value=p[4];$('end').value=p[5];if(['custom','gig','night'].includes(active))document.querySelector('.settings').open=true;controls();render();};$('days').onclick=e=>{const b=e.target.closest('[data-day]');if(!b)return;const d=+b.dataset.day;workdays=workdays.includes(d)?workdays.filter(x=>x!==d):[...workdays,d];active='custom';controls();render();};document.querySelectorAll('input,select').forEach(el=>el.addEventListener('change',()=>{if(['start','end'].includes(el.id)){active='custom';controls();}render();}));window.AddressPlanner.init(render);controls();render();})();
